import cv2
import numpy as np

def embed_data(image_path, data, output_path):
    img = cv2.imread(image_path)
    data += '%%EOF'
    data_bin = ''.join([format(ord(i), '08b') for i in data])
    data_len = len(data_bin)

    idx = 0
    for row in img:
        for pixel in row:
            for channel in range(3):
                if idx < data_len:
                    pixel[channel] = pixel[channel] & ~1 | int(data_bin[idx])
                    idx += 1
    cv2.imwrite(output_path, img)

